      const value=window.EmboSolutionVisuals?.[projectId]?.[kind],source=typeof value==='string'?value:value?.src||value?.url;
      if(!source)return `<figure class="system-card-art system-card-svg" data-solution-visual="${kind}" data-visual-fallback>${fallback()}</figure>`;
      const count=Math.max(1,Math.min(6,Number(value?.panels)||1)),panel=Math.max(0,Math.min(count-1,Number(value?.panel)||0));
      const vertical=value?.direction==='vertical';
      const geometry=vertical?`width:100%;height:${count*100}%;left:0;top:${-panel*100}%`:`width:${count*100}%;height:100%;left:${-panel*100}%;top:0`;
      return `<figure class="system-card-art system-generated-visual" data-solution-visual="${kind}"><img src="${esc(source)}" alt="${esc(title)}" loading="lazy" decoding="async" style="${geometry}">${kind==='sensors'?`<div class="system-perception-labels" aria-hidden="true">${cards.views.map(([label])=>`<span>${esc(label)}</span>`).join('')}</div>`:''}</figure>`;
